import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第三十九章 不孝的孩子不如拐杖","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/39第三十九章 不孝的孩子不如拐杖.md","filePath":"meditation/巴利文大藏经/39第三十九章 不孝的孩子不如拐杖.md"}'),_={name:"meditation/巴利文大藏经/39第三十九章 不孝的孩子不如拐杖.md"};function r(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第三十九章-不孝的孩子不如拐杖" tabindex="-1">第三十九章 不孝的孩子不如拐杖 <a class="header-anchor" href="#第三十九章-不孝的孩子不如拐杖" aria-label="Permalink to &quot;第三十九章 不孝的孩子不如拐杖&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应14经/大财富者经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，舍卫城中一位家财万贯的婆罗门，他穿着破烂的衣服，灰头土脸的来到佛陀的住所，顶礼佛陀后这位婆罗门在一旁坐下。</p><p>佛陀对这位婆罗门说：“婆罗门，你穿的衣服为何如此的破烂？如来看你好像很久都没有洗过澡了。你应该是舍卫城中的富翁吧，你怎么会变成这样？”</p><p>婆罗门说：“世尊，是这样的，我的四个儿子与儿媳妇，他们八个人合谋将我赶出了家门，他们认为我现在老了，什么事情也干不了，是家里面的累赘，浪费家里面的粮食。”</p><p>佛陀说：“婆罗门，如来给你说一些法，当你们婆罗门教徒举行聚会的时候，你就可以讲给参与聚会的大众听，你的儿子和儿媳也会参加婆罗门教徒的聚会吧？”</p><p>婆罗门回答：“世尊，我的儿子和儿媳，他们也是婆罗门教徒，他们肯定也会参加婆罗门教徒的聚会的，因为婆罗门阶层的人在我们的国家地位是很崇高的。世尊，您准备为我说什么法，您请说。”</p><p>佛陀说：“婆罗门，你听好了：我亲爱的孩子，当你们出生的时候我欢天喜地，我细心照顾你们，养育你们慢慢长大成人，我希望你们长大后能够干一番大事业。可是你们却与儿媳妇合谋将我赶出家门，就如同赶走狗和猪那样，毫不留情。你们是不孝顺、品行低劣的孩子，你们虽然喊我：「老爹，老爹」。可是你们的行为却如同凶暴的恶鬼，你们看见我白发苍颜、老态龙钟，如同衰老无用的马，于是就不再奉养我，就将白发苍苍、老眼昏花的我赶出家门。我有四个儿子，我有四个儿媳妇，既然会流落街头、无家可归，我家财万贯、富甲一方却要沿街乞讨、风吹雨淋。我的这些儿子还比不上我手上拿着的拐杖，我可以用拐杖驱赶走凶猛的牛，驱赶走凶恶的狗。在黑夜中，拐杖能为我在前面探路，渡溪流的时候，拐杖还可以为我判断溪流的深浅，让我找到合适的站立点。这个拐杖的威神力真大，它能够将跌倒的我扶起来，它是我的依靠，实在是比我亲生的儿子还要好呀。”</p><p>这时，佛陀说偈言：</p><p>「我素喜其生，我希其生长。</p><p>彼等与妻谋，逐我如豚犬。</p><p>虽非喜贤者，亦呼我为父。</p><p>唯子夜叉形，舍去我年老。</p><p>如老哀弱马，不予饮食物。</p><p>我乃此子父，虽身为长者。</p><p>但乞他家食，有此不孝子。</p><p>不如我拐杖，可拂逐猛牛。</p><p>亦可逐猛犬，暗中能导我。</p><p>在于深溪时，并作定足基。</p><p>依此拐杖力，倒而又得起。」</p><p>佛陀说法后，婆罗门说：“世尊，您说的太好了，您能为我再说一遍吗？世尊，我年纪大了，一下子记不住这么多法语偈言。”</p><p>佛陀于是又为婆罗门重复几遍的说法，直到婆罗门记下了所有的法语偈言后，佛陀才停止了重复说法。</p><p>婆罗门再次顶礼佛陀，欢喜的离开了。</p><p>当婆罗门教徒举行聚会大典的时候，这位婆罗门就在聚会大典上讲说佛陀的法语偈言，在座的所有婆罗门都称赞他说的好，甚至于聚会大典上德高望重的婆罗门长老都恭敬的邀请他坐在最尊贵的位置上。这些婆罗门长老亲自记录下他说出的这些法语偈言，准备作为婆罗门教的经典流通世间。这位婆罗门的儿子、儿媳坐在台下，听到父亲如此的指责他们，又看见德高望重的婆罗门长老如此的恭敬父亲，顿时羞愧难当、无地自容。聚集大会举行完毕后，这位婆罗门的儿子、儿媳就将老父亲请回家，让老父亲洗澡，给老父亲准备可口的饭菜，还为老父亲买了几套新衣服。这位婆罗门吃完可口的饭菜，穿上新买的衣服，就再次来到佛陀的住所，他顶礼佛陀后，在一旁坐下，这位婆罗门对佛陀说：“世尊，感谢您！感谢您！我在聚会大典上讲说您的法语偈言，得到了大众的称赞，连德高望重的婆罗门长老都亲自邀请我坐到最尊贵的位置上，我的儿子、儿媳在举行完聚会大典后，就将我接回家中，他们现在对我非常的恭敬，他们让我洗澡，为我做可口的饭菜吃，为我买崭新的衣服穿。世尊，我无法用言语来表达对您的感激之情。世尊，我现在带来了一些新衣服和一些财物，请您接受我对您最恭敬的供养吧，请您让我做您的在家修行弟子吧，我愿意受持您制定的戒律，我愿意按您的正法去修行，您就是我最尊贵的老师，请老师您收下我对您最恭敬的供养吧，我无法报答您对我的教导之恩，只是想用这些微薄的供养表达对您的崇敬之情。”</p><p>佛陀看见婆罗门如此的恭敬虔诚，于是就接受了他的皈依和供养。</p>',26)]))}const f=t(_,[["render",r]]);export{m as __pageData,f as default};
